parameters.jsonBody:
={{ JSON.stringify({
  query: `mutation {
    createPost(input: {
      text: ${JSON.stringify($('Post Content').item.json.output['post content'] + "\n\n" + $json.output.Hashtags.join(' '))},
      channelId: "6ae33c752f1f5ed6480ddab3",
      schedulingType: automatic,
      mode: addToQueue,
      saveToDraft: true
    }) {
      ... on PostActionSuccess { post { id text } }
      ... on MutationError { message }
    }
  }`
}) }}

